// Given: the trace recorder. Do not edit this file.
//
// Algorithms can call the ambient `trace` to describe what they are doing,
// one step at a time. By default it does nothing, so tests and exercise
// signatures never depend on it. A visual turns it on with recordTrace(),
// collects the steps as frames, and replays them in the player.
//
//   if (trace.enabled) trace.step("project A onto axis n0", [{ kind: "arrow", from, to }]);
//
// Checking `trace.enabled` first is optional: it only skips building the
// primitives when nobody is recording.
import type { Vec2 } from "../math/vec2";

/** Optional colour for a primitive: a palette name or any CSS colour. */
export type PrimColor = "a" | "b" | "normal" | "contact" | "muted" | "highlight" | (string & {});

/** What a trace step can draw, in world coordinates (metres, y up). */
export type DrawPrim =
  | { kind: "point"; p: Vec2; label?: string; color?: PrimColor }
  | { kind: "segment"; a: Vec2; b: Vec2; label?: string; color?: PrimColor }
  | { kind: "arrow"; from: Vec2; to: Vec2; label?: string; color?: PrimColor }
  | { kind: "circle"; c: Vec2; r: number; color?: PrimColor }
  | { kind: "polygon"; pts: Vec2[]; color?: PrimColor }
  | { kind: "text"; p: Vec2; text: string; color?: PrimColor };

export interface Trace {
  /** True while something is recording. */
  readonly enabled: boolean;
  /** Start a named group of steps, for example "boxVsBox". Groups can nest. */
  begin(title: string): void;
  /** Record one step: a label, what to draw, and any numbers worth showing. */
  step(label: string, prims: DrawPrim[], values?: Record<string, number>): void;
  /** Close the most recent group. */
  end(): void;
}

/** One recorded step. `group` is the path of open groups, for example ["step", "boxVsBox"]. */
export type Frame = {
  group: string[];
  label: string;
  prims: DrawPrim[];
  values: Record<string, number>;
};

export type Recording = { frames: Frame[] };

// Primitives and values are copied on record, so later mutation of the
// algorithm's vectors (bodies are mutable) cannot rewrite history.
function copy<T>(x: T): T {
  return structuredClone(x);
}

class Recorder implements Trace {
  readonly enabled = true;
  readonly frames: Frame[] = [];
  private groups: string[] = [];

  begin(title: string): void {
    this.groups.push(title);
  }
  step(label: string, prims: DrawPrim[], values: Record<string, number> = {}): void {
    this.frames.push({ group: [...this.groups], label, prims: copy(prims), values: { ...values } });
  }
  end(): void {
    this.groups.pop();
  }
}

const noop: Trace = { enabled: false, begin() {}, step() {}, end() {} };
let sink: Trace = noop;

/** The ambient trace. Call it from any algorithm; it is a no-op unless recording. */
export const trace: Trace = {
  get enabled() {
    return sink.enabled;
  },
  begin: (title) => sink.begin(title),
  step: (label, prims, values) => sink.step(label, prims, values),
  end: () => sink.end(),
};

/**
 * Runs fn with recording on and returns the frames it produced.
 * Recording stops even if fn throws (the error is rethrown).
 * Calls can nest: the inner call records its own frames only.
 */
export function recordTrace(fn: () => void): Recording {
  const previous = sink;
  const recorder = new Recorder();
  sink = recorder;
  try {
    fn();
  } finally {
    sink = previous;
  }
  return { frames: recorder.frames };
}
